<script setup>
import { computed } from 'vue'
import { packageById, percent, state, wordTotal } from '../stores/lexigo'
const average = computed(() => state.attempts.length ? Math.round(state.attempts.reduce((sum, attempt) => sum + percent(attempt.score, attempt.total), 0) / state.attempts.length) : 0)
</script>
<template><section class="mx-auto max-w-5xl px-5 py-14"><p class="text-[11px] font-bold tracking-[.15em] text-lexi">LEARNING INSIGHTS</p><h1 class="mt-2 font-display text-5xl font-bold">Progress overview</h1><p class="mt-2 text-slate-500">A simple record of every completed practice session.</p><div class="mt-8 grid gap-4 sm:grid-cols-3"><article v-for="item in [{ label: 'Practice sessions', value: state.attempts.length }, { label: 'Average score', value: `${average}%` }, { label: 'Words available', value: wordTotal }]" :key="item.label" class="rounded-2xl border border-slate-200 bg-white p-5"><p class="text-sm text-slate-500">{{ item.label }}</p><b class="mt-2 block font-display text-4xl text-lexi">{{ item.value }}</b></article></div><div v-if="state.attempts.length" class="mt-8 rounded-2xl border border-slate-200 bg-white p-5"><div class="mb-3 flex justify-between"><h2 class="font-display text-2xl font-bold">Recent activity</h2><span class="text-xs font-bold text-slate-400">SCORE</span></div><article v-for="attempt in state.attempts" :key="attempt.id" class="flex items-center gap-3 border-t border-slate-100 py-4"><span class="grid h-8 w-8 place-items-center rounded-full bg-emerald-100 font-bold text-emerald-600">✓</span><div><b class="block text-sm">{{ packageById(attempt.packageId)?.name || 'Deleted package' }}</b><small class="text-slate-500">{{ new Date(attempt.at).toLocaleDateString() }}</small></div><strong class="ml-auto" :class="percent(attempt.score, attempt.total) >= 70 ? 'text-emerald-600' : ''">{{ attempt.score }}/{{ attempt.total }} · {{ percent(attempt.score, attempt.total) }}%</strong></article></div><div v-else class="mt-8 rounded-2xl border border-dashed border-slate-300 bg-white p-14 text-center"><p class="text-4xl">🌱</p><h2 class="mt-3 font-display text-2xl font-bold">Your learning story starts here</h2><RouterLink to="/library" class="mt-5 inline-block rounded-xl bg-lexi px-4 py-3 text-sm font-bold text-white">Browse packages</RouterLink></div></section></template>
